  'remove {name}? it stops syncing; the files it put stay.': ['odebrat {name}? přestane synchronizovat; soubory, které nahrál, zůstanou.', 'odobrať {name}? prestane synchronizovať; súbory, ktoré nahral, zostanú.', 'eltávolítja: {name}? leáll a szinkronizálás; a feltöltött fájlok megmaradnak.', 'retirer {name} ? la synchro s’arrête ; les fichiers envoyés restent.', '{name} entfernen? der Abgleich hört auf; die übertragenen Dateien bleiben.'],
  'remove {name}? nobody can log in to it with osada any more.': ['odebrat {name}? už se do něj nikdo nepřihlásí přes osada.', 'odobrať {name}? už sa doň nikto neprihlási cez osada.', 'eltávolítja: {name}? ezután senki sem tud belépni a osada-fiókjával.', 'retirer {name} ? plus personne ne pourra s’y connecter avec osada.', '{name} entfernen? niemand kann sich dort mehr mit osada anmelden.'],
